package com.habitpro.controller;import com.habitpro.model.StickyNote;import com.habitpro.repository.StickyNoteRepository;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/notes") public class NoteController{private final StickyNoteRepository repo;public NoteController(StickyNoteRepository r){repo=r;}public record NoteInput(String title,String content,String deadline,String remindAt,String color){}@GetMapping public List<StickyNote> all(Authentication a){return repo.findByUserIdOrderByPinnedDescCreatedAtDesc(a.getName());}@PostMapping public ResponseEntity<?> add(@RequestBody NoteInput in,Authentication a){if(in.content()==null||in.content().isBlank())return ResponseEntity.badRequest().body(Map.of("message","Note content is required"));StickyNote n=new StickyNote();n.setUserId(a.getName());apply(n,in);return ResponseEntity.ok(repo.save(n));}@PutMapping("/{id}")public ResponseEntity<?> update(@PathVariable String id,@RequestBody NoteInput in,Authentication a){var o=repo.findByIdAndUserId(id,a.getName());if(o.isEmpty())return ResponseEntity.notFound().build();if(in.content()==null||in.content().isBlank())return ResponseEntity.badRequest().body(Map.of("message","Note content is required"));StickyNote n=o.get();apply(n,in);return ResponseEntity.ok(repo.save(n));}private void apply(StickyNote n,NoteInput i){n.setTitle(i.title()==null||i.title().isBlank()?"Untitled note":i.title().trim());n.setContent(i.content().trim());n.setDeadline(i.deadline());n.setRemindAt(i.remindAt());n.setColor(i.color()==null||i.color().isBlank()?"yellow":i.color());}@PatchMapping("/{id}/pin")public ResponseEntity<?> pin(@PathVariable String id,Authentication a){var o=repo.findByIdAndUserId(id,a.getName());if(o.isEmpty())return ResponseEntity.notFound().build();var n=o.get();n.setPinned(!n.isPinned());return ResponseEntity.ok(repo.save(n));}@DeleteMapping("/{id}")public ResponseEntity<?> delete(@PathVariable String id,Authentication a){var o=repo.findByIdAndUserId(id,a.getName());if(o.isEmpty())return ResponseEntity.notFound().build();repo.delete(o.get());return ResponseEntity.noContent().build();}}